use crate::{bq062 as b,catalog,model::*,rules::*,unit_support::*,abi112_review_play_tests::Trace};
fn setup()->(Game,String){let mut g=game();fund(&mut g,0,"BQ064",2);let id=held(&mut g,b::ID,0);(g,id)}
fn play(id:&str,mode:&str,target:Option<&str>)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::KEY.into()),option:Some(mode.into()),target_id:target.map(str::to_string),..Action::new("play")}}
fn top(g:&mut Game){for _ in 0..16{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!();}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn bq062_original_all_modes_closed_and_no_extra_payload(){let(mut g,id)=setup();let c=catalog::card(b::ID);assert_eq!((c.cost,c.color.as_str(),c.supported),(2,"灰",false));assert_eq!(c.subtypes,["命令","研究","隐秘对抗"]);assert!(matches!(b::definition().abilities[0].timing,Timing::Standard));for n in 0..3{let mut d=b::definition();d.abilities[0].modes[n].ops.clear();assert!(b::validate_definition(b::ID,&d).is_err());}reject(&mut g,0,play(&id,"investigate",Some("society:p0")));reject(&mut g,0,play(&id,"all",None));g.players[0].assets.clear();reject(&mut g,0,play(&id,"contest",None));}
#[test]fn bq062_investigation_single_current_recipient_then_complete_forecast(){let(mut g,id)=setup();let token=field(&mut g,"TK010",0);let before=g.icons(g.board(&token).unwrap().1,0).investigation;let enemy=field(&mut g,"TK010",1);let ordinary=field(&mut g,"JC125",0);act(&mut g,0,play(&id,"investigate",None));top(&mut g);let p=g.pending.clone().unwrap();assert_eq!(p.choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>(),[token.clone()]);for v in [vec![],vec![enemy],vec![ordinary]]{reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),selected:Some(v),..Action::new("choose")});}choose(&mut g,vec![token.clone()]);assert_eq!(g.board(&token).unwrap().1.permanent_investigation_markers,1);assert_eq!(g.icons(g.board(&token).unwrap().1,0).investigation,before+1);let p=g.pending.clone().unwrap();assert_eq!(p.choice.kind,"investigation");reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),top:Some(vec![]),bottom:Some(vec![]),..Action::new("choose")});let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();act(&mut g,0,Action{choice_id:Some(p.choice.id),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});restore(&mut g);assert!(g.hide_in_place(&token));let c=g.regions[0].cards.iter().find(|c|c.definition=="TK010").unwrap();assert_eq!(c.permanent_investigation_markers,0);restore(&mut g);}
#[test]fn bq062_empty_recipient_forecasts_zero_one_two_and_parked_core_untouched(){for n in 0..3{let(mut g,id)=setup();g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));let c=g.make_card("BQ046",0);g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:Some(c)});g.players[0].deck.truncate(n);act(&mut g,0,play(&id,"investigate",None));top(&mut g);assert_eq!(g.core_zones[0].card.as_ref().unwrap().permanent_investigation_markers,0);if n==0{assert!(g.pending.is_none());}else{let p=g.pending.clone().unwrap();assert_eq!((p.choice.min,p.choice.max),(Some(n),Some(n)));let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();act(&mut g,0,Action{choice_id:Some(p.choice.id),top:Some(vec![]),bottom:Some(ids),..Action::new("choose")});}restore(&mut g);}}
#[test]fn bq062_lock_hidden_draw_and_stale_target(){for stale in [false,true]{let(mut g,id)=setup();let target=field(&mut g,"JC125",1);g.board_mut(&target).unwrap().face_down=true;let hand=g.players[0].hand.len();act(&mut g,0,play(&id,"lock",Some(&target)));if stale{g.remove_dead(&target,RemovalCause::Destroy);g.drive().unwrap();}top(&mut g);if stale{assert_eq!(g.players[0].hand.len(),hand-1);}else{assert_eq!(g.board(&target).unwrap().1.lock_markers,1);assert_eq!(g.players[0].hand.len(),hand);}restore(&mut g);}}
#[test]fn bq062_marker_moves_counts_and_cannot_survive_private_zone(){let(mut g,id)=setup();let token=field(&mut g,"TK010",0);g.players[0].deck.clear();act(&mut g,0,play(&id,"investigate",None));top(&mut g);choose(&mut g,vec![token.clone()]);let other=field(&mut g,"JC125",0);let prepared=g.prepare_marker_move(&token,&other).unwrap();g.commit_marker_move_counters(prepared).unwrap();assert_eq!(g.board(&token).unwrap().1.permanent_investigation_markers,0);assert_eq!(g.board(&other).unwrap().1.permanent_investigation_markers,1);assert_eq!(crate::batch4_politician::marker_count(g.board(&other).unwrap().1),1);let mut x=g.clone();let c=x.remove_board(&other).unwrap().1;x.players[0].hand.push(c);bad(&g,&x);g.remove_dead(&other,RemovalCause::Destroy);g.drive().unwrap();assert!(g.players[0].graveyard.iter().all(|c|c.permanent_investigation_markers==0));restore(&mut g);}
#[test]fn bq062_restore_rejects_frame_and_choice_corruption(){let(mut g,id)=setup();field(&mut g,"TK010",0);act(&mut g,0,play(&id,"investigate",None));for n in 0..4{let mut x=g.clone();let i=x.stack.last_mut().unwrap();if n==0{i.frame=None;}else{let f=i.frame.as_mut().unwrap();match n{1=>f.source.card.definition="JC001".into(),2=>f.steps.clear(),_=>f.already_paid.clear()}}bad(&g,&x);}top(&mut g);for n in 0..4{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.choice.options.clear(),1=>p.choice.min=Some(0),2=>p.seat=1,_=>{let ChoiceResolution::Frame{frame,..}=&p.resolution else{panic!()};x.effects.push_back(Effect::Frame{frame:frame.clone()});}}bad(&g,&x);}restore(&mut g);}
fn choice(t:&mut Trace,p:&Pending){if matches!(p.choice.kind.as_str(),"investigation"|"order"){t.action(p.seat,Action{choice_id:Some(p.choice.id.clone()),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});}else{t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn prepared(mode:&str,index:usize,command:bool)->serde_json::Value{let(mut g,id)=setup();let target=if mode=="investigate"{field(&mut g,"TK010",0)}else{field(&mut g,"JC125",1)};for seat in 0..4{held(&mut g,if seat==0&&!command{"JC125"}else{"BQ060"},seat);}let mut t=Trace::new_preserving_rng(g,format!("bq062-prepared-{mode}-{command}"),index);t.action(0,play(&id,mode,if mode=="lock"{Some(&target)}else{None}));for _ in 0..100{if let Some(p)=t.room.game.pending.clone(){choice(&mut t,&p);}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty()&&t.room.game.mystic_contest.is_none(){break;}else{t.pass();}}let g=&t.room.game;assert!(g.pending.is_none()&&g.mystic_contest.is_none());match mode{"investigate"=>assert_eq!(g.board(&target).unwrap().1.permanent_investigation_markers,1),"lock"=>assert_eq!(g.board(&target).unwrap().1.lock_markers,1),_=>{assert_eq!(g.mystic_history.len(),1);let o=&g.mystic_history[0];assert_eq!(o.shown[0].value,if command{5}else{0});assert!(o.shown[1..].iter().all(|s|s.value==1));let mut x=g.clone();x.mystic_history[0].shown[0].value+=4;bad(g,&x);}}duplicate(t.value())}
fn natural()->serde_json::Value{use crate::deck;fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="bq062-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("BQ064",3),("JC125",44)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let d=deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq062".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
 let(seed,g)=(1..4097).find_map(|seed|{let g=construct(seed);(g.players[0].hand.iter().any(|c|c.definition==b::ID)&&g.players[0].hand.iter().filter(|c|c.definition=="BQ064").count()>=2).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"bq062-natural-paid-lock-and-draw".into(),790);let mut done=false;for _ in 0..900{if let Some(p)=t.room.game.pending.clone(){if matches!(p.choice.kind.as_str(),"investigation"|"order"){choice(&mut t,&p);}else{let mut options=p.choice.options.iter().collect::<Vec<_>>();options.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&matches!(c.definition.as_str(),"BQ062"|"BQ064")));t.choose(options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let target=g.regions.iter().flat_map(|r|&r.cards).find(|c|c.controller==0&&c.definition=="JC125"&&!c.face_down);let a=if g.players[0].assets.len()<2{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="BQ064")))}else if target.is_none(){legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC125")))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY)&&a.action.option.as_deref()==Some("lock")&&a.action.target_id.as_deref()==target.map(|c|c.id.as_str()))};if let Some(a)=a{if a.action.kind=="play"{done=true;}t.action(0,a.action.clone());}else{t.pass();}}
 assert!(done);assert!(t.room.game.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="JC125"&&c.controller==0&&c.lock_markers==1));let mut v=t.value();v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn bq062_native_three_modes_and_natural_export(){let cases=vec![natural(),prepared("investigate",791,true),prepared("lock",792,true),prepared("contest",793,true),prepared("contest",794,false)];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/bq062.rs",include_bytes!("bq062.rs").as_slice()),("rust-game/src/bq062_tests.rs",include_bytes!("bq062_tests.rs").as_slice()),("rust-game/src/marker_transfer.rs",include_bytes!("marker_transfer.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("BQ062_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn bq062_live_core_marker_actual_copy_counts_once(){let(mut g,id)=setup();g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));let core=field(&mut g,"BQ046",0);g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:None});g.players[0].deck.clear();let before=g.icons(g.board(&core).unwrap().1,0).investigation;act(&mut g,0,play(&id,"investigate",None));top(&mut g);choose(&mut g,vec![core.clone()]);assert_eq!(g.icons(g.board(&core).unwrap().1,0).investigation,before+1);g.begin_window(Window::Action(0));fund(&mut g,0,"XQ21",1);let fee=field(&mut g,"JC125",0);let spell=held(&mut g,"XQ21",0);act(&mut g,0,Action{card_id:Some(spell),ability_id:Some("batch4-xq21-copy-marker".into()),target_id:Some(core.clone()),cost_selected:Some(vec![fee]),..Action::new("play")});top(&mut g);assert!(g.pending.as_ref().unwrap().choice.options.iter().any(|o|o.id=="permanent-investigation"));choose(&mut g,vec!["permanent-investigation".into()]);assert_eq!(g.board(&core).unwrap().1.permanent_investigation_markers,2);assert_eq!(g.icons(g.board(&core).unwrap().1,0).investigation,before+2);restore(&mut g);}
